/**
 * crypto-shim-playground.js — the browser half of the playground engine.
 *
 * The playground engine is the REAL package bytes (generated by
 * scripts/build-playground.mjs, which rewrites only their `node:crypto`
 * import lines to point here). This file therefore must implement exactly
 * the synchronous surface those packages use:
 *
 *   createHash("sha256")  -> update(data...).digest("hex" | undefined)
 *   createHmac("sha256", key) -> update(data...).digest("hex" | undefined)
 *   timingSafeEqual(a, b) -> boolean
 *
 * SHA-256 is implemented here in plain JS (no WebCrypto, which is async and
 * would break the ledger's atomic synchronous reserve — the entire point of
 * CG-BUD/1's no-await property). Verified against Node's crypto with the
 * FIPS 180-4 test vectors by the playground contract test.
 *
 * NOT a general drop-in: only the exact calls above are provided, and calling
 * anything else throws by construction (fail-loud beats silent divergence).
 */

const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

function sha256Bytes(data) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const len = data.length;
  const paddedLen = len + 9 <= 64 ? 64 : (((len + 9) + 63) & ~63);
  const message = new Uint8Array(paddedLen);
  message.set(data);
  message[len] = 0x80;
  const hi = Math.floor(len / 0x20000000);
  const lo = (len * 8) >>> 0;
  message[paddedLen - 8] = hi >>> 24;
  message[paddedLen - 7] = (hi >>> 16) & 0xff;
  message[paddedLen - 6] = (hi >>> 8) & 0xff;
  message[paddedLen - 5] = hi & 0xff;
  message[paddedLen - 4] = lo >>> 24;
  message[paddedLen - 3] = (lo >>> 16) & 0xff;
  message[paddedLen - 2] = (lo >>> 8) & 0xff;
  message[paddedLen - 1] = lo & 0xff;

  const w = new Array(64).fill(0);
  for (let off = 0; off < paddedLen; off += 64) {
    for (let i = 0; i < 16; i++) {
      const j = off + i * 4;
      w[i] = (((message[j] << 24) | (message[j + 1] << 16) | (message[j + 2] << 8) | message[j + 3]) >>> 0);
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0;
    H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0;
    H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0;
    H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0;
    H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => [
    x >>> 24 & 0xff, (x >>> 16) & 0xff, (x >>> 8) & 0xff, x & 0xff,
  ]).flat();
}

function toBytes(input) {
  if (input instanceof Uint8Array) return input;
  if (typeof input === "string") return new TextEncoder().encode(input);
  throw new TypeError("update: only strings and Uint8Array are supported by the playground shim");
}

function hex(bytes) {
  let out = "";
  for (const b of bytes) out += b.toString(16).padStart(2, "0");
  return out;
}

export function createHash(algorithm) {
  if (algorithm !== "sha256") throw new TypeError(`createHash: the playground shim implements only sha256 (got "${algorithm}")`);
  const chunks = [];
  let digested = false;
  return {
    update(data) {
      if (digested) throw new Error("update after digest is illegal");
      chunks.push(toBytes(data));
      return this;
    },
    digest(encoding) {
      if (digested) throw new Error("digest called twice");
      let total = chunks.reduce((n, c) => n + c.length, 0);
      const data = new Uint8Array(total);
      let off = 0;
      for (const c of chunks) { data.set(c, off); off += c.length; }
      const bytes = sha256Bytes(data);
      digested = true;
      if (encoding === undefined) return new Uint8Array(bytes);
      if (encoding === "hex") return hex(bytes);
      throw new TypeError(`digest: the playground shim implements only hex (got "${encoding}")`);
    },
  };
}

function hmacBytes(message, keyBytes) {
  let block = keyBytes;
  if (block.length > 64) {
    block = sha256Bytes(block);
  }
  const padKey = new Uint8Array(64);
  padKey.set(block);
  const innerMessage = new Uint8Array(Math.min(64, padKey.length) + message.length);
  const outerMessage = new Uint8Array(64 + 32);
  let offIn = 0;
  for (let i = 0; i < 64; i++) {
    innerMessage[offIn] = padKey[i] ^ 0x36;
    outerMessage[i] = padKey[i] ^ 0x5c;
    offIn++;
  }
  innerMessage.set(message, offIn);
  const inner = sha256Bytes(innerMessage);
  outerMessage.set(inner, 64);
  return sha256Bytes(outerMessage);
}

export function createHmac(algorithm, key) {
  if (algorithm !== "sha256") throw new TypeError(`createHmac: the playground shim implements only sha256 (got "${algorithm}")`);
  const keyBytes = toBytes(String(key));
  const messageChunks = [];
  let finalized = false;
  return {
    update(data) {
      if (finalized) throw new Error("update after digest is illegal");
      messageChunks.push(toBytes(data));
      return this;
    },
    digest(encoding) {
      if (finalized) throw new Error("digest called twice");
      finalized = true;
      let total = messageChunks.reduce((n, c) => n + c.length, 0);
      const message = new Uint8Array(total);
      let off = 0;
      for (const c of messageChunks) { message.set(c, off); off += c.length; }
      const bytes = hmacBytes(message, keyBytes);
      if (encoding === "hex") return hex(bytes);
      if (encoding === undefined) return new Uint8Array(bytes);
      throw new TypeError(`digest: the playground shim implements only hex (got "${encoding}")`);
    },
  };
}

export function timingSafeEqual(a, b) {
  if (!(a instanceof Uint8Array) || !(b instanceof Uint8Array)) {
    throw new TypeError("timingSafeEqual: both arguments must be Uint8Array");
  }
  if (a.length !== b.length) throw new Error("timingSafeEqual: inputs must have equal length");
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

export default { createHash, createHmac, timingSafeEqual };
